<div class="d-flex justify-content-between align-items-center mb-4"><h3>إشعارات المنصة</h3><a class="btn btn-outline-secondary" href="<?= url('/employee/dashboard') ?>">اللوحة</a></div><div class="list-group"><?php foreach($notifications as $n): ?><a class="list-group-item list-group-item-action" href="<?= url($n['link'] ?? '/employee/dashboard') ?>"><div class="d-flex justify-content-between"><strong><?= e($n['title']) ?></strong><small class="text-muted"><?= e($n['created_at']) ?></small></div><div class="small"><?= e($n['message']) ?></div></a><?php endforeach; if(!$notifications): ?><div class="alert alert-light border">لا توجد إشعارات.</div><?php endif; ?></div>